def kruskal_mst(graph: Dict[str, List[Tuple[str, int]]]) -> Dict[str, List[Tuple[str, int]]]:
    """
    Compute the Minimum Spanning Tree (MST) of the graph using Kruskal's algorithm.
    """
    # Initialize MST
    mst = {node: [] for node in graph}

    # Union-Find data structure
    parent = {node: node for node in graph}
    rank = {node: 0 for node in graph}

    def find(node):
        if parent[node] != node:
            parent[node] = find(parent[node])
        return parent[node]

    def union(node1, node2):
        root1 = find(node1)
        root2 = find(node2)
        if root1 != root2:
            if rank[root1] > rank[root2]:
                parent[root2] = root1
            elif rank[root1] < rank[root2]:
                parent[root1] = root2
            else:
                parent[root2] = root1
                rank[root1] += 1

    # Sort edges by weight
    edges = []
    for node, neighbors in graph.items():
        for neighbor, weight in neighbors:
            edges.append((weight, node, neighbor))
    edges.sort()

    # Build MST
    for weight, node, neighbor in edges:
        if find(node) != find(neighbor):
            union(node, neighbor)
            mst[node].append((neighbor, weight))
            mst[neighbor].append((node, weight))

    return mst

