        return 0.0, [source]

    def dual_graph(graph):
        # Construct the dual graph
        dual = {}
        for node, edges in graph.items():
            for neighbor, weight in edges:
                if neighbor not in dual:
                    dual[neighbor] = []
                dual[node].append((neighbor, weight))
                dual[neighbor].append((node, weight))
        return dual

