        path = [face_b]
        while face_b in dual and dual[face_b]:
            face_b = dual[face_b][0][0]
            path.append(face_b)
        return list(reversed(path))

    def astar_search(dual, source, target):
        # A* search for shortest path in dual graph
        if source == target:
            return 0.0, [source]

        unvisited = [(0, source)]
        visited = {}
        parent = {}
        distance = {}

        while unvisited:
            _, current_face = heappop(unvisited)
            if current_face == target:
                return distance[current_face], reconstruct_path(dual, target)
