                    distance[neighbor_face] = new_distance
                    heappush(unvisited, (new_distance, neighbor_face))
                    parent[neighbor_face] = current_face

        return float("inf"), None

    dual = dual_graph(graph)
    distance, path = astar_search(dual, source, target)
    return distance, path

